package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen1Test {



















    @Test
    public void testParseOctal_LargeValue() {
        // Max octal for long is roughly 17777777777777777777 (too big for signed long)
        // Let's use a large but safe one
        byte[] buffer = "7777777777".getBytes(); 
        long expected = Long.parseLong("7777777777", 8);
        assertEquals(expected, TarUtils.parseOctal(buffer, 0, buffer.length));
    }






}

